ns.Data.OtherWeapons = {
  note = "Enhancement is a two-hander spec in Forever (dual wield removed). Icy Veins Enhancement leveling (updated Nov 13): Weapon DPS is always the first priority while leveling; aim for a slow 2-handed weapon, ideally 3.3-3.8 speed; visit a weapon trainer in Orgrimmar early to learn Two-Handed Maces and Axes. Icy Veins stat priority (Nov 13): slow 2H at ~3.3 or slower; Stormstrike is normalized to 3.3 for two-handers; after the post-launch hotfixes Windfury Weapon + Windfury Totem are the priority, which favours slow, heavy-hitting weapons (bigger Windfury swings, highest Maelstrom Weapon proc chance). Blizzard Nov 10 hotfix: Weapon imbues and weapon totems now stack; Maelstrom Weapon procs 6/7/8/9/10 times per minute by rank (tooltip example: 5 points + 3.6-speed weapon = 60% per swing vs 33% at 2.0 speed). Blizzard developer note: Enhancement had drifted to Spell Power/Intellect gear; the hotfix moves it back to a Windfury-friendly gearing direction before raids open. Strength is now slightly ahead of Intellect per point (Icy Veins, after the Mental Dexterity nerf). Elemental/Restoration: staves and caster weapons from the Icy Veins tables; Wowhead pre-raid lists also use one-hand + off-hand.",
  source_url = "https://www.icy-veins.com/wow-forever/enhancement-shaman-melee-dps-pve-stat-priority",
  other_sources = { "https://www.icy-veins.com/wow-forever/enhancement-shaman-leveling", "https://news.blizzard.com/en-us/article/24315281/wow-forever-hotfixes-november-13-2026" },
  checked = "2026-11-14",
}

ns.Data.BiS = {
  status = "Icy Veins Elemental / Enhancement / Restoration gear pages (updated Nov 9, 2026): 'It's too early to tell' / 'Currently a work in progress' - no level-60 or pre-raid items listed. Wowhead (pages modified 2026-11-14) publishes rough Phase 1 pre-raid estimates for Elemental and Restoration (imported as 'level 60 pre-raid', unconfirmed); its Enhancement tables are all empty ('-'). Raids open 2026-12-09; item stats hidden until first looted (raid_rules).",
  flag = "No Enhancement pre-raid list anywhere. Wowhead's Enhancement text still recommends Spell damage/Intellect gear 'due to the scaling of Flametongue Weapon together with Windfury Totem' - that predates the Nov 10 hotfix and is stale. Wowhead tier-set bonuses are Beta placeholders (the Elemental 5-piece even references Lava Burst, which was removed).",
  other_sources = { "https://www.icy-veins.com/wow-forever/enhancement-shaman-melee-dps-pve-gear-best-in-slot", "https://www.icy-veins.com/wow-forever/elemental-shaman-ranged-dps-pve-gear-best-in-slot", "https://www.icy-veins.com/wow-forever/restoration-shaman-healer-pve-gear-best-in-slot", "https://www.wowhead.com/forever/guide/classes/shaman/enhancement/bis-gear", "https://www.wowhead.com/forever/guide/classes/shaman/elemental/bis-gear", "https://www.wowhead.com/forever/guide/classes/shaman/restoration/bis-gear" },
